import itertools
fT={'t':t,'t2':t**2,'cos t':np.cos(t),'sin t':np.sin(t),'exp(-t)':np.exp(-t),'1/t':1/t,'sqrt t':np.sqrt(t),'log t':np.log(t)}
fX={'x':x,'x2':x**2,'cos x':np.cos(x),'sin x':np.sin(x),'exp(-x)':np.exp(-x),'1/x':1/x,'sqrt x':np.sqrt(x),'x3':x**3,'log x':np.log(x)}
fV={'v':v,'v2':v**2,'cos v':np.cos(v),'sin v':np.sin(v),'exp(-v)':np.exp(-v),'1/v':1/v,'v3':v**3,'log v':np.log(v)}
terms={}
for a,fa in fT.items(): terms[a]=fa
for b,fb in fX.items(): terms[b]=fb
for c_,fc in fV.items(): terms[c_]=fc
for a,fa in fT.items():
  for b,fb in fX.items(): terms[a+'*'+b]=fa*fb
  for c_,fc in fV.items(): terms[a+'*'+c_]=fa*fc
for b,fb in fX.items():
  for c_,fc in fV.items(): terms[b+'*'+c_]=fb*fc
keys=list(terms); print(len(keys))
sv=np.sqrt(v); y=dv_dt; vy=np.var(y)
res=[]
for i,j in itertools.combinations(range(len(keys)),2):
    M=np.column_stack([sv,terms[keys[i]],terms[keys[j]]])
    if not np.all(np.isfinite(M)): continue
    cc=np.linalg.lstsq(M,y,rcond=None)[0]
    r=np.mean((M@cc-y)**2)/vy
    res.append((r,keys[i],keys[j],np.round(cc,4)))
res.sort(key=lambda z:z[0])
